}
.container-fluid.white .subtext {
  color: inherit;
}
.subtext {
  color: #fff;
  margin: 80px auto;
}
.subtext p:last-child {
  margin-bottom: 0;
}
.subtext .subtitle {
  font-size: 20px;
  margin-bottom: 20px;
  font-family: RobotoSlab-Bold;
}
.follow_height {
  display: block;
}
.vertical_center {
  top: 50%;
  position: relative;
  transform: translateY(-50%);
}
.desktop_disp {
  display: block !important;
}
.desktop_disp.inline {
  display: inline-block !important;
}
.mobile_disp,
.mobile_disp.inline {
  display: none !important;
}
.no_margin {
  margin: 0;
}
.contact_frame {
  max-width: 1200px;
  margin: 0 auto;
}
.contact_form {
  font-size: 18px;
}
.contact_form input {
  width: 100%;
  border: none;
  border-radius: 0;
  padding: 6px 14px;
  margin-bottom: 20px;
  transition: color 500ms ease, outline-color 500ms ease;
}
.contact_form input::placeholder {
  opacity: 1;
  color: #00577b;
}
.contact_form input:focus {
  border-color: transparent;
  outline: 3px solid #00577b;
}
.contact_form label {
  font-size: 20px;
  line-height: 1em;
  font-weight: normal;
  margin-bottom: 10px;
  font-family: RobotoSlab-Regular;
}
.contact_form textarea {
  width: 100%;
  border: none;
  resize: vertical;
  min-height: 120px;
  padding: 6px 14px;
  border-radius: 0;
  margin-bottom: 20px;
  transition: color 500ms ease, outline-color 500ms ease;
}
.contact_form textarea::placeholder {
  opacity: 1;
  color: #00577b;
}
.contact_form textarea:focus {
  outline: 3px solid #00577b;
}
.contact_form .send_btn_frame {
  display: table;
  float: right;
}
.contact_form .send_btn_frame button {
  height: 40px;
  border: none;
  color: #fff;
  font-size: 20px;
  padding: 0px 20px;
  border-radius: 2px;
  background-color: #0d6990;
  transition: all 500ms ease;
}
.contact_form .send_btn_frame button:hover,
.contact_form .send_btn_frame button:focus {
  color: #00577b;
  background-color: #fff;
}
.contact_form .line {
  display: table-row;
}
.contact_form .block {
  display: table-cell;
}
.contact_form .send_ico {
  width: 90px;
  margin-left: 20px;
}
input.error,
textarea.error {
  color: #da1717;
  margin-bottom: 0px;
  outline: 3px solid #da1717;
}
label.error {
  color: #00577b;
}
input.valid,
textarea.valid {
  outline: 3px solid #3e7a04;
}
label.error {
  font-size: 13px;
  padding-left: 0px;
}
body.facturacion .link_rack li:hover,
body.facturacion .link_rack li.active {
  background-color: #f8e356;
}
.link_rack {
  list-style: none;
  padding-left: 0px;
  font-family: RobotoSlab-Bold;
}
.link_rack li {
  padding: 6px 8px;
  border-radius: 2px;
  transition: all 500ms ease;
}
.link_rack li a {
  text-decoration: none;
}
.link_rack li:hover,
.link_rack li.active {
  background-color: #fff;
}
.title {
